#!/usr/bin/env python3
"""Copy the shared TypeScript (web/src, the single source) into the Creator project as generated files.

Node runs web/src with explicit ".ts" import suffixes; Creator's compiler wants none, so the copy drops them. The copy is generated and
git-ignored: edit web/src, then run this and rebuild.

  python3 shared/sync_ts.py
"""
import os
import re
import shutil

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
SRC = os.path.join(ROOT, "web/src")
DST = os.path.join(ROOT, "mini/assets/scripts/shared")
FILES = ["proto/schema.ts", "proto/codec.ts", "proto/frame.ts", "md5.ts", "net.ts", "session.ts", "login.ts", "city.ts"]  # not messages.ts: types only

shutil.rmtree(DST, ignore_errors=True)
for f in FILES:
    out = os.path.join(DST, f)
    os.makedirs(os.path.dirname(out), exist_ok=True)
    text = open(os.path.join(SRC, f)).read()
    text = re.sub(r'(from\s+"\.{1,2}/[^"]+)\.ts"', r'\1"', text)
    open(out, "w").write("// Generated by shared/sync_ts.py from web/src/" + f + ". Do not edit.\n" + text)
print(f"synced {len(FILES)} files to mini/assets/scripts/shared")
